-module(formata_yamerl_SUITE_construction_int).

-include_lib("eunit/include/eunit.hrl").

-define(FILENAME, "test/fixtures/yamerl/construction/int.yaml").

setup() ->
    ok.

schema_failsafe_simple_test_() ->
    {setup,
      fun setup/0,
      [
        ?_assertMatch(
          [
            [
              "0", "+0", "-0",
              "123", "+123", "-123",
              "0b101", "+0b101", "-0b101",
              "0o123", "+0o123", "-0o123",
              "0123", "+0123", "-0123",
              "0x1aB", "+0x1aB", "-0x1aB",
              "123:1:23", "+123:1:23", "-123:1:23",
              "1_234", "0b10_10", "0o12_34", "012_34", "0xc3_A9", "1_234:56:8",
              "Not an int", "+Not an int", "-Not an int"
            ]
          ],
          formata_yamerl_constr:file(?FILENAME,
            [{detailed_constr, false}, {schema, failsafe}]) %% No integer parsing
        )
      ]
    }.

