% YAML 1.2 core permits signs only on decimal integers (section 10.3.2).
schema_failsafe_int_simple_test_() ->
    {setup,
      fun setup/0,
      [
        ?_assertMatch(
          [
            [
              0, 0, 0,
              123, 123, -123,
              "0b101", "+0b101", "-0b101",
              83, "+0o123", "-0o123",
              123, 123, -123,
              427, "+0x1aB", "-0x1aB",
              "123:1:23", "+123:1:23", "-123:1:23",
              "1_234", "0b10_10", "0o12_34", "012_34", "0xc3_A9", "1_234:56:8",
              "Not an int", "+Not an int", "-Not an int"
            ]
          ],
          formata_yamerl_constr:file(?FILENAME,
            [{detailed_constr, false}, {schema, failsafe},
              {node_mods, [formata_yamerl_node_int]}])
        )
      ]
    }.

schema_failsafe_int_ext_simple_test_() ->
    {setup,
      fun setup/0,
      [
        ?_assertMatch(
          [
            [
              0, 0, 0,
              123, 123, -123,
              5, 5, -5,
              "0o123", "+0o123", "-0o123",
